import { useState, useCallback, useEffect, useRef } from 'react';
import Cropper from 'react-easy-crop';
import 'react-easy-crop/react-easy-crop.css';

const createImage = (url) =>
  new Promise((resolve, reject) => {
    const image = new Image();
    image.addEventListener('load', () => resolve(image));
    image.addEventListener('error', reject);
    image.src = url;
    image.crossOrigin = 'anonymous';
  });

const getCroppedImg = async (imageSrc, pixelCrop) => {
  const image = await createImage(imageSrc);
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');

  canvas.width = pixelCrop.width;
  canvas.height = pixelCrop.height;

  ctx.drawImage(
    image,
    pixelCrop.x,
    pixelCrop.y,
    pixelCrop.width,
    pixelCrop.height,
    0,
    0,
    pixelCrop.width,
    pixelCrop.height
  );

  return canvas.toDataURL('image/jpeg', 0.92);
};

function App() {
  const [imageSrc, setImageSrc] = useState('');
  const [crop, setCrop] = useState({ x: 0, y: 0 });
  const [zoom, setZoom] = useState(1);
  const [croppedAreaPixels, setCroppedAreaPixels] = useState(null);
  const [loading, setLoading] = useState(true);

  const fileInputRef = useRef(null);

  useEffect(() => {
    window.Telegram?.WebApp.ready();
    window.Telegram?.WebApp.expand();

    const params = new URLSearchParams(window.location.search);
    const photoUrl = params.get('photo');

    if (photoUrl) {
      setImageSrc(decodeURIComponent(photoUrl));
    } else {
      alert('Фото не передано из бота!');
    }
    setLoading(false);
  }, []);

  const onCropComplete = useCallback((_, croppedAreaPixels) => {
    setCroppedAreaPixels(croppedAreaPixels);
  }, []);

  const handleCrop = async () => {
    if (!croppedAreaPixels || !imageSrc) return;

    try {
      const croppedBase64 = await getCroppedImg(imageSrc, croppedAreaPixels);

      // Скачивание файла
      const link = document.createElement('a');
      link.href = croppedBase64;
      link.download = 'cropped_15x10.jpg';
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      // Уведомление в Telegram
      window.Telegram?.WebApp.showPopup({
        message: '✅ Фото обрезано и скачано! Теперь отправь его боту.',
      });

      // Закрыть Mini App (раскомментируй при необходимости)
      // window.Telegram?.WebApp.close();
    } catch (err) {
      alert('Ошибка при обрезке: ' + err);
    }
  };

  if (loading) {
    return <div className="text-center p-8 text-white">Загрузка фото...</div>;
  }

  return (
    <div className="min-h-screen bg-black text-white flex flex-col">
      <div className="p-4 text-center font-bold text-xl border-b border-gray-800">
        Обрежь фото до 15×10
      </div>

      <div className="relative flex-1 bg-black" style={{ maxHeight: '70vh' }}>
        {imageSrc && (
          <Cropper
            image={imageSrc}
            crop={crop}
            zoom={zoom}
            aspect={15 / 10}
            onCropChange={setCrop}
            onZoomChange={setZoom}
            onCropComplete={onCropComplete}
            showGrid={true}
            cropShape="rect"
            style={{
              containerStyle: { background: '#000' },
              cropAreaStyle: { border: '3px solid #fff' },
            }}
          />
        )}
      </div>

      {/* Ползунок зума */}
      <div className="p-4 bg-gray-900">
        <div className="flex items-center gap-3">
          <span className="text-sm">🔍</span>
          <input
            type="range"
            min={1}
            max={5}
            step={0.01}
            value={zoom}
            onChange={(e) => setZoom(Number(e.target.value))}
            className="flex-1 accent-blue-500"
          />
          <span className="text-sm w-8 text-right">{zoom.toFixed(1)}×</span>
        </div>
      </div>

      <div className="p-4">
        <button
          onClick={handleCrop}
          disabled={!croppedAreaPixels}
          className="w-full bg-green-600 hover:bg-green-500 py-4 rounded-2xl text-lg font-bold disabled:opacity-50"
        >
          ✅ Обрезать и отправить (15×10)
        </button>

        <p className="text-center text-xs text-gray-400 mt-4">
          Перетаскивай фото пальцами или мышкой<br />
          Используй ползунок для приближения
        </p>
      </div>
    </div>
  );
}

export default App;